/**
 * भारत · विशेष — "जब मेरे तीरों की वर्षा होगी" (BharataSpecialReel). Every cut and hit sits on the voice clock (timing.ts,
 * generated by bharata-special-arjuna/tools/vo_prep.py). Look: golden-hour illustrated epic (world.tsx), soft-shaded busts
 * (cast.tsx), Arjuna archery close-up (arjuna.tsx), props (props.tsx). Captions: centred Tiro Devanagari serif + parva tag.
 */
import React from "react";
import { AbsoluteFill, Audio, Img, staticFile, useCurrentFrame } from "remotion";
import { loadFont as loadTiro } from "@remotion/google-fonts/TiroDevanagariHindi";
import { ArjunaCloseUp, ArjunaDefs } from "./arjuna";
import { Bust, Conch, Figure, LOOKS, type Expr, type Look } from "./cast";
import { Cattle, CrownShatter, DashaPhone, SleepWave, ShamiTree } from "./props";
import { BEATS, ENV, PHRASES, TOTAL, WORDS } from "./timing";
import { ArrowStorm, Army, ChariotSmall, H, HeroChariotFar, P, Plain, Sky, W, WorldDefs, clamp, ease, inv, lerp, rng } from "./world";

const { fontFamily: TIRO } = loadTiro();
export const BHARATA_SPECIAL_TOTAL = TOTAL;

const ph = (i: number) => PHRASES[i];
const word = (needle: string, after = 0) => WORDS.find((w) => w.a >= after && w.w.includes(needle))?.a ?? after;
const env = (f: number) => ENV[Math.max(0, Math.min(ENV.length - 1, f))] ?? 0;
const speaking = (f: number, who: string) => PHRASES.some((p) => p.who === who && f >= p.a - 1 && f <= p.b + 1);
const mouthOf = (f: number, who: string) => (speaking(f, who) ? clamp(env(f) * 1.1) : 0);
const blink = (f: number, seed: number) => {
  const per = 74 + (seed % 5) * 9;
  const k = (f + seed * 13) % per;
  return k < 2 ? 0.1 : k < 4 ? 0.5 : 1;
};

// ---------- cut list (frames) ----------
const C = {
  storm: BEATS.storm[0] - 2,
  wide: ph(2).a - 1,
  title: BEATS.title[0],
  rewind: ph(4).a - 1,
  uttara: ph(5).a - 3,
  reveal: ph(7).a - 2,
  forest: ph(8).a - 2,
  cows: ph(10).a - 2,
  run: ph(11).a - 2,
  fierce: ph(13).a - 2,
  shami: ph(14).a - 2,
  conch: ph(16).a - 2,
  horses: ph(17).a - 2,
  drona: ph(18).a - 2,
  duryo: ph(20).a - 2,
  bhishma: ph(21).a - 2,
  volley: BEATS.volley[0],
  flee: ph(24).a - 2,
  astra: ph(26).a - 2,
  sleep: BEATS.astra[0] + 4,
  order: ph(28).a - 2,
  collect: ph(29).a - 2,
  awake: word("बेसुध", ph(29).a) - 8,
  duryo2: ph(30).a - 2,
  bhishma2: ph(31).a - 2,
  salute: ph(33).a - 2,
  crown: ph(34).a - 2,
  feature: ph(35).a - 2,
  send: ph(38).a - 2,
};
const crownHit = word("मुकुट", ph(34).a) + 6;

// ---------- small helpers ----------
const Svg: React.FC<{ children: React.ReactNode; cam?: { s?: number; x?: number; y?: number; ox?: number; oy?: number }; shake?: number }> = ({ children, cam = {}, shake = 0 }) => {
  const { s = 1, x = 0, y = 0, ox = W / 2, oy = H * 0.55 } = cam;
  return (
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{ position: "absolute", inset: 0 }}>
      <WorldDefs />
      <ArjunaDefs />
      <g transform={`translate(${ox + x + shake},${oy + y}) scale(${s}) translate(${-ox},${-oy})`}>{children}</g>
      <rect width={W} height={H} fill="url(#ep-vig)" />
      <defs>
        <radialGradient id="ep-vig" cx="0.5" cy="0.45" r="0.78">
          <stop offset="0.62" stopColor="#000" stopOpacity="0" />
          <stop offset="1" stopColor="#1a0a04" stopOpacity="0.5" />
        </radialGradient>
      </defs>
    </svg>
  );
};
const kick = (f: number, at: number, amp = 14, len = 9) => (f >= at && f < at + len ? (f % 2 ? 1 : -1) * amp * (1 - (f - at) / len) : 0);
const push = (f: number, a: number, rate = 0.0011) => 1 + (f - a) * rate;

/** Painted backdrop for busts: sky + soft battlefield below, sun on the side the speaker faces. */
const Backdrop: React.FC<{ f: number; sunX: number; sunY?: number; horizon?: number; dim?: number; army?: boolean; seed?: number }> = ({ f, sunX, sunY = 620, horizon = 1460, dim = 0, army = true, seed = 9 }) => (
  <g>
    <Sky sunX={sunX} sunY={sunY} f={f + seed * 50} dim={dim} />
    <g filter="url(#sp-blur10)">
      <Plain horizon={horizon} f={f} sunX={sunX} dim={dim} />
      {army && <Army horizon={horizon} front={horizon + 160} x0={-100} x1={1180} f={f} rows={9} sFront={1.1} seed={seed} />}
    </g>
  </g>
);

const Speaker: React.FC<{ f: number; a: number; look: Look; who: string; flip?: boolean; e?: Expr; sunX?: number; dim?: number; s?: number; x?: number; y?: number; extra?: React.ReactNode; army?: boolean }> = ({
  f,
  a,
  look,
  who,
  flip = false,
  e = {},
  sunX,
  dim = 0,
  s = 1.32,
  x,
  y,
  extra,
  army = true,
}) => {
  const lf = f - a;
  const bx = x ?? (flip ? 290 : -290);
  const by = y ?? -420;
  return (
    <Svg cam={{ s: push(f, a, 0.0009) }}>
      <Backdrop f={f} sunX={sunX ?? (flip ? 180 : 900)} dim={dim} army={army} seed={look.id.length + 3} />
      <Bust look={look} f={lf} flip={flip} x={bx} y={by} s={s} e={{ mouth: mouthOf(f, who), eye: blink(f, look.id.length), ...e }} />
      {extra}
    </Svg>
  );
};

// ---------- captions ----------
const WHO_TAG: Record<string, string> = { kaal: "विराट पर्व", arjuna: "अर्जुन · विराट पर्व", uttara: "उत्तर · विराट पर्व", drona: "द्रोण · विराट पर्व", duryo: "दुर्योधन · विराट पर्व", bhishma: "भीष्म · विराट पर्व" };
const Captions: React.FC<{ f: number }> = ({ f }) => {
  if (f >= C.send) return null;
  const i = PHRASES.findIndex((p, k) => f >= p.a - 3 && f < (PHRASES[k + 1]?.a ?? p.b + 20) - 3 && f <= p.b + 18);
  if (i < 0) return null;
  const p = PHRASES[i];
  const text = WORDS.filter((w) => w.p === i).map((w) => w.w).join(" ");
  const o = Math.min(inv(f, p.a - 3, p.a + 4), 1 - inv(f, p.b + 10, p.b + 18));
  const long = text.length > 34;
  return (
    <div style={{ position: "absolute", left: 60, right: 60, top: 1180, textAlign: "center", opacity: o }}>
      <div style={{ fontFamily: TIRO, fontSize: long ? 54 : 62, lineHeight: 1.34, color: "#fff8ec", textShadow: "0 2px 18px rgba(30,12,4,0.9), 0 0 4px rgba(30,12,4,0.7)" }}>{text}</div>
      <div style={{ display: "inline-block", marginTop: 22, padding: "5px 16px", background: "rgba(36,20,10,0.55)", border: "1px solid rgba(255,222,170,0.35)", borderRadius: 4, fontFamily: TIRO, fontSize: 26, letterSpacing: 2, color: "#f6dfb6" }}>
        {WHO_TAG[p.who] ?? "विराट पर्व"}
      </div>
    </div>
  );
};

const BrandBug: React.FC = () => (
  <div style={{ position: "absolute", left: 44, top: 70, display: "flex", alignItems: "center", gap: 14, padding: "8px 20px 8px 8px", borderRadius: 44, background: "rgba(30,16,8,0.45)", border: "1px solid rgba(255,220,160,0.35)" }}>
    <Img src={staticFile("jyotiq/logo-zodiac.png")} style={{ width: 62, height: 62, borderRadius: 31 }} />
    <div style={{ fontFamily: TIRO, fontSize: 34, color: "#fff2da" }}>Jyotiq</div>
  </div>
);
const Flash: React.FC<{ f: number; at: number; len?: number; color?: string; max?: number }> = ({ f, at, len = 8, color = "#fff6e0", max = 1 }) => {
  const o = f >= at && f < at + len ? max * (1 - (f - at) / len) : 0;
  return o > 0 ? <AbsoluteFill style={{ background: color, opacity: o }} /> : null;
};

// ---------- shots ----------
const ShotArcher: React.FC<{ f: number; a: number; release: number; astra?: boolean; dusk?: number }> = ({ f, a, release, astra = false, dusk = 0 }) => {
  const lf = f - a;
  const draw = lerp(0.8, 1, ease(inv(f, a, release - 6)));
  const rel = f >= release ? inv(f, release, release + 16) : 0;
  return (
    <Svg cam={{ s: push(f, a, 0.0018) + (f > release - 40 && f < release ? (f - release + 40) * 0.0016 : 0) }} shake={kick(f, release, 16)}>
      <Sky sunX={880} sunY={600} f={f + 200} dim={dusk} />
      <g filter="url(#sp-blur10)">
        <Plain horizon={1500} f={f} sunX={880} dim={dusk} />
        <Army horizon={1500} front={1640} x0={500} x1={1200} f={f} rows={9} sFront={1.1} seed={9} />
      </g>
      <g filter="url(#sp-blur4)">
        <line x1={150} y1={1920} x2={150} y2={260} stroke={P.goldDark} strokeWidth={14} />
        <path d={`M156,280 C230,${270 + Math.sin(f / 5) * 12} 300,${300 + Math.sin(f / 6) * 14} 380,${290 + Math.sin(f / 5 + 1) * 12} L372,${430 + Math.sin(f / 6) * 12} C300,${440 + Math.sin(f / 5) * 10} 230,420 156,430 Z`} fill="url(#sp-gold)" />
      </g>
      {astra && f < release && <circle cx={1000} cy={620} r={180 + Math.sin(f / 2) * 20} fill="#cbb8ff" opacity={0.25 + 0.4 * inv(f, a, release)} filter="url(#sp-blur24)" />}
      <g transform="translate(-300,-430) scale(1.36)">
        <ArjunaCloseUp f={lf} draw={draw} released={rel} />
      </g>
      {rel > 0 && <line x1={700} y1={760} x2={1100} y2={620} stroke={astra ? "#e6dcff" : "#fff3c8"} strokeWidth={12} opacity={0.7 * (1 - rel)} filter="url(#sp-blur4)" />}
    </Svg>
  );
};

const ShotStorm: React.FC<{ f: number; a: number; n?: number }> = ({ f, a, n = 1300 }) => {
  const lf = f - a;
  const dim = 0.72 * ease(inv(lf, 6, 50));
  return (
    <Svg cam={{ s: 1.06 + 0.0012 * lf, oy: H * 0.6 }}>
      <Sky sunX={560} sunY={1020} f={f + 400} dim={dim} rays={1 - dim} />
      <Plain horizon={1300} f={f} sunX={560} dim={dim * 0.8} />
      <Army horizon={1300} front={1520} x0={-120} x1={1200} f={f} rows={14} sFront={1.7} seed={4} bhishma />
      <ArrowStorm f={lf} n={n} from={[-260, 1700]} to={[700, 1420]} spread={900} apex={1250} dur={40} launch={44} scale={1.15} seed={11} />
      <ArrowStorm f={lf - 5} n={Math.round(n * 0.4)} from={[-200, 1900]} to={[900, 1500]} spread={700} apex={900} dur={30} launch={40} scale={1.8} seed={12} />
    </Svg>
  );
};

const ShotWide: React.FC<{ f: number; a: number; dimT?: number; chariot?: boolean; extra?: React.ReactNode; wave?: number; dim?: number }> = ({ f, a, dimT = 0, chariot = true, extra, wave = 0, dim = 0 }) => {
  const lf = f - a;
  const g = ease(inv(lf, 0, 150));
  return (
    <Svg cam={{ s: lerp(1.12, 1.0, g), x: lerp(40, -30, g), oy: H * 0.62 }}>
      <Sky sunX={560} sunY={800} f={f + 600} dim={dim} />
      <circle cx={560} cy={800} r={150} fill="#fff6dc" opacity={0.55 * (1 - dim)} filter="url(#sp-blur24)" />
      <Plain horizon={880} f={f} sunX={560} dim={dim} />
      <Army horizon={880} front={1120} x0={-160} x1={1240} f={f} rows={18} sFront={1.6} seed={3} bhishma wave={wave} />
      <rect x={-200} y={820} width={W + 400} height={140} fill={P.haze} opacity={0.35 * (1 - dim)} filter="url(#sp-blur24)" />
      {chariot && <HeroChariotFar x={540} y={1640} s={1.35} f={f} />}
      {extra}
      <rect width={W} height={H} fill="#140804" opacity={dimT * 0.55} />
    </Svg>
  );
};

const ShotForest: React.FC<{ f: number; a: number }> = ({ f, a }) => {
  const lf = f - a;
  const r = rng(5);
  const trees = Array.from({ length: 26 }, (_, i) => ({ x: r() * 1200 - 60, h: 700 + r() * 900, w: 30 + r() * 50, d: i / 26 }));
  return (
    <Svg cam={{ s: 1.05 + lf * 0.0008 }}>
      <rect width={W} height={H} fill="#1a2030" />
      <circle cx={760} cy={420} r={90} fill="#f4ecd8" opacity={0.9} />
      <circle cx={760} cy={420} r={300} fill="#c8d4f0" opacity={0.15} filter="url(#sp-blur24)" />
      {trees.map((t, i) => (
        <g key={i} opacity={0.4 + t.d * 0.6}>
          <rect x={t.x} y={1920 - t.h} width={t.w} height={t.h} fill={t.d > 0.6 ? "#0c1018" : "#202838"} />
          <ellipse cx={t.x + t.w / 2} cy={1920 - t.h} rx={t.w * 3} ry={t.w * 2.2} fill={t.d > 0.6 ? "#0e1410" : "#243028"} />
        </g>
      ))}
      {/* five small figures walking into the dark: the twelve years again */}
      {[0, 1, 2, 3, 4].map((i) => (
        <Figure key={i} x={420 + i * 56 - lf * 0.6} y={1560 + (i % 2) * 10} s={0.9 - i * 0.04} f={f + i * 5} run={0.25} cloth="#3a3020" skin="#2a2018" />
      ))}
      <rect y={1500} width={W} height={420} fill="#0a0c12" opacity={0.6} />
      <text x={540} y={760} textAnchor="middle" fontFamily={TIRO} fontSize={260} fill="#e8e0cc" opacity={0.16 + 0.1 * Math.sin(lf / 10)}>१२</text>
    </Svg>
  );
};

