const ShotShami: React.FC<{ f: number; a: number }> = ({ f, a }) => {
  const open = ease(inv(f, ph(15).a, ph(15).a + 30));
  const glow = ease(inv(f, BEATS.gandiva[0] - 10, BEATS.gandiva[0] + 10));
  return (
    <Svg cam={{ s: lerp(1.0, 1.35, ease(inv(f, a, BEATS.gandiva[1]))), oy: 860, ox: 640 }}>
      <Sky sunX={300} sunY={1100} f={f + 1200} dim={0.35} rays={0.6} />
      <Plain horizon={1380} f={f} sunX={300} dim={0.4} />
      <ShamiTree f={f} open={open} glow={glow} />
      <Figure x={420} y={1530} s={2.4} f={f} cloth="#d99a2a" skin="#cc9268" crown />
      <Figure x={560} y={1540} s={2.5} f={f} cloth="#c22b33" skin="#c4865b" braid />
    </Svg>
  );
};

const ShotConch: React.FC<{ f: number; a: number }> = ({ f, a }) => {
  const at = BEATS.conch[0];
  const blast = f >= at ? inv(f, at, at + 30) : 0;
  return (
    <Svg cam={{ s: push(f, a, 0.0012) }} shake={kick(f, at, 18, 14)}>
      <Backdrop f={f} sunX={900} />
      <Bust look={LOOKS.arjuna} f={f - a} x={-290} y={-420} s={1.32} e={{ brow: 0.6, eye: f > at - 10 ? 0.4 : blink(f, 3) }} hand={<Conch x={640} y={960} s={1.1} r={-8} />} />
      {blast > 0 &&
        [0, 0.15, 0.3].map((d, i) => {
          const q = clamp(blast - d);
          return q > 0 ? <circle key={i} cx={1000} cy={980} r={q * 900} fill="none" stroke="#fff4d8" strokeWidth={30 * (1 - q)} opacity={1 - q} /> : null;
        })}
    </Svg>
  );
};

