const ShotCrown: React.FC<{ f: number; a: number }> = ({ f, a }) => {
  const p = f >= crownHit ? inv(f, crownHit, crownHit + 40) : 0;
  const arrowIn = inv(f, crownHit - 12, crownHit);
  const look = f >= crownHit ? { ...LOOKS.duryo, id: "duryoBare", hair: "bare" as const } : LOOKS.duryo;
  return (
    <Svg cam={{ s: push(f, a, 0.001) + (f >= crownHit ? 0.04 * ease(inv(f, crownHit, crownHit + 8)) : 0) }} shake={kick(f, crownHit, 22, 12)}>
      <Backdrop f={f} sunX={180} />
      <Bust look={look} f={f - a} flip x={290} y={-420} s={1.32} e={{ mouth: f >= crownHit ? 0.5 * (1 - p) + 0.2 : 0, wide: f >= crownHit ? 1 : 0, brow: f >= crownHit ? -0.8 : 0.4, eye: f >= crownHit ? 1 : blink(f, 4), smile: f < crownHit ? 0.6 : 0 }} />
      {arrowIn > 0 && arrowIn < 1 && <line x1={lerp(1200, 650, arrowIn) - 160} y1={lerp(300, 470, arrowIn) - 40} x2={lerp(1200, 650, arrowIn)} y2={lerp(300, 470, arrowIn)} stroke="#24140a" strokeWidth={8} />}
      <CrownShatter x={620} y={480} p={p} s={1.2} />
    </Svg>
  );
};

const ShotFeature: React.FC<{ f: number; a: number }> = ({ f, a }) => {
  const lf = f - a;
  const phone = ease(inv(f, ph(36).a - 10, ph(36).a + 14));
  return (
    <Svg cam={{ s: 1.04 + lf * 0.0005 }}>
      <Sky sunX={540} sunY={1060} f={f + 1500} dim={0.25} />
      <Plain horizon={1240} f={f} sunX={540} dim={0.3} />
      {/* Arjuna's silhouette on the car at sunset */}
      <g transform={`translate(${lerp(0, -220, phone)},0)`}>
        <HeroChariotFar x={540} y={1500} s={2.6} f={f} />
      </g>
      <DashaPhone x={lerp(1400, 720, phone)} y={1000} s={0.95} p={phone} f={f} />
    </Svg>
  );
};

const ShotSend: React.FC<{ f: number; a: number }> = ({ f, a }) => {
  const lf = f - a;
  return (
    <AbsoluteFill>
      <Svg cam={{ s: 1.02 + lf * 0.0004 }}>
        <Sky sunX={540} sunY={1000} f={f + 1800} dim={0.45} />
        <Plain horizon={1200} f={f} sunX={540} dim={0.5} />
        <g opacity={0.9}>
          <Bust look={LOOKS.arjuna} f={lf} x={-560} y={-260} s={1.12} e={{ eye: blink(f, 1), brow: 0.4 }} />
          <Bust look={{ ...LOOKS.duryo, id: "karna", cloth: "#e8b030", clothDark: "#8a5a14", armour: "#f0c860", beard: "none", hair: "princeCrown" }} f={lf} flip x={560} y={-260} s={1.12} e={{ eye: blink(f, 2), brow: 0.4 }} />
        </g>
      </Svg>
      <div style={{ position: "absolute", left: 0, right: 0, top: 430, textAlign: "center", fontFamily: TIRO, opacity: ease(inv(lf, 0, 12)) }}>
        <div style={{ fontSize: 120, color: "#ffe7b0", textShadow: "0 6px 30px rgba(40,10,0,0.9)" }}>अर्जुन या कर्ण?</div>
      </div>
      <div style={{ position: "absolute", left: 80, right: 80, top: 1180, textAlign: "center", fontFamily: TIRO, opacity: ease(inv(lf, 6, 20)) }}>
        <div style={{ fontSize: 50, lineHeight: 1.35, color: "#fff8ec", textShadow: "0 2px 18px rgba(30,12,4,0.9)" }}>{"जो दोस्त कर्ण को बड़ा धनुर्धर मानता है…\nउसे ये ज़रूर भेजिए"}</div>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 14, marginTop: 30, padding: "14px 34px", borderRadius: 40, background: "rgba(243,194,79,0.92)", color: "#2a1404", fontSize: 40 }}>
          <svg width={40} height={40} viewBox="0 0 24 24"><path d="M2 21l21-9L2 3v7l15 2-15 2z" fill="#2a1404" /></svg>
          भेजिए
        </div>
      </div>
      {lf > 200 && (
        <div style={{ position: "absolute", left: 0, right: 0, top: 860, textAlign: "center", opacity: ease(inv(lf, 200, 220)) }}>
          <Img src={staticFile("jyotiq/logo-zodiac.png")} style={{ width: 150, height: 150, borderRadius: 75, boxShadow: "0 0 0 4px #f3c24f" }} />
        </div>
      )}
    </AbsoluteFill>
  );
};

const ShotTitle: React.FC<{ f: number }> = ({ f }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top: 640, textAlign: "center", opacity: ease(inv(f, C.title + 2, C.title + 18)), transform: `scale(${lerp(1.08, 1, ease(inv(f, C.title, C.title + 40)))})` }}>
    <div style={{ fontFamily: TIRO, fontSize: 40, letterSpacing: 10, color: "#f3d39a" }}>भारत · विशेष</div>
    <div style={{ width: 220, height: 2, background: "linear-gradient(90deg,transparent,#f3c24f,transparent)", margin: "22px auto" }} />
    <div style={{ fontFamily: TIRO, fontSize: 84, lineHeight: 1.25, color: "#fff4dc", textShadow: "0 4px 30px rgba(60,20,0,0.9)", whiteSpace: "pre-line" }}>{"जब मेरे तीरों की\nवर्षा होगी"}</div>
  </div>
);

const Rewind: React.FC<{ f: number; a: number; b: number }> = ({ f, a, b }) => {
  if (f < a || f >= b) return null;
  const q = inv(f, a, b);
  return (
    <AbsoluteFill style={{ mixBlendMode: "screen", pointerEvents: "none" }}>
      <svg width={W} height={H}>
        {Array.from({ length: 18 }, (_, i) => (
          <rect key={i} x={((i * 173 - f * 60) % 1400) - 200} y={i * 107} width={300 + (i % 4) * 120} height={4} fill="#fff2d6" opacity={0.35 * (1 - q)} />
        ))}
      </svg>
      <div style={{ position: "absolute", left: 60, top: 260, fontFamily: TIRO, fontSize: 44, color: "#ffe9c0", opacity: 1 - q * 0.6 }}>⏪</div>
    </AbsoluteFill>
  );
};

/** Frame-0 mute hook headline (sound-off viewers): 3–5 words, clear of the top and bottom fifths. */
const MuteHook: React.FC<{ f: number }> = ({ f }) => {
  if (f > 100) return null;
  const o = Math.min(1, 1 - inv(f, 80, 100));
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: 410, textAlign: "center", opacity: o }}>
      <div style={{ display: "inline-block", padding: "10px 30px", background: "rgba(30,12,4,0.55)", borderRadius: 10, fontFamily: TIRO, fontSize: 58, color: "#ffe39a", textShadow: "0 2px 12px rgba(0,0,0,0.7)" }}>
        एक योद्धा · पूरी कौरव सेना
      </div>
    </div>
  );
};

export const BharataSpecialReel: React.FC<{ audio?: boolean }> = ({ audio = true }) => {
  const f = useCurrentFrame();
  const release = ph(1).b - 2;
  let shot: React.ReactNode;
  if (f < C.storm) shot = <ShotArcher f={f} a={0} release={release} />;
  else if (f < C.wide) shot = <ShotStorm f={f} a={C.storm} />;
  else if (f < C.rewind) shot = <ShotWide f={f} a={C.wide} dimT={inv(f, C.title, C.title + 16)} />;
  else if (f < C.uttara) shot = <ShotWide f={f} a={C.wide} dimT={0.6} dim={0.4} />;
  else if (f < C.reveal) shot = <Speaker f={f} a={C.uttara} look={LOOKS.uttara} who="uttara" e={{ wide: 1, brow: -1, look: -0.6 }} sunX={900} />;
  else if (f < C.forest) shot = <Speaker f={f} a={C.reveal} look={LOOKS.brihannala} who="none" e={{ brow: 0.3, smile: f > word("अर्जुन", C.reveal) ? 0.4 : 0 }} extra={f > word("अर्जुन", C.reveal) ? <circle cx={300} cy={760} r={420} fill="#fff0c0" opacity={0.18} filter="url(#sp-blur50)" /> : null} />;
  else if (f < C.cows) shot = <ShotForest f={f} a={C.forest} />;
  else if (f < C.run) shot = <ShotCows f={f} a={C.cows} />;
  else if (f < C.fierce) shot = <ShotRun f={f} a={C.run} />;
  else if (f < C.shami) shot = <ShotFierce f={f} a={C.fierce} />;
  else if (f < C.conch) shot = <ShotShami f={f} a={C.shami} />;
  else if (f < C.horses) shot = <ShotConch f={f} a={C.conch} />;
  else if (f < C.drona) shot = <ShotHorses f={f} a={C.horses} />;
  else if (f < C.duryo) shot = <Speaker f={f} a={C.drona} look={LOOKS.drona} who="drona" flip e={{ wide: 0.7, brow: -0.2 }} />;
  else if (f < C.bhishma) shot = <Speaker f={f} a={C.duryo} look={LOOKS.duryo} who="duryo" flip e={{ smile: 0.8, brow: 0.6 }} />;
  else if (f < C.volley) shot = <Speaker f={f} a={C.bhishma} look={LOOKS.bhishma} who="bhishma" flip e={{ brow: 0.1 }} />;
  else if (f < C.flee) shot = <ShotStorm f={f} a={C.volley} n={1600} />;
  else if (f < C.astra) shot = <ShotFlee f={f} a={C.flee} />;
  else if (f < C.sleep) shot = <ShotArcher f={f} a={C.astra} release={BEATS.astra[0] + 2} astra />;
  else if (f < C.order) shot = <ShotWide f={f} a={C.sleep} chariot wave={inv(f, C.sleep + 10, C.order - 10)} extra={<SleepWave cx={540} cy={1200} p={inv(f, C.sleep, C.sleep + 50)} />} />;
  else if (f < C.collect) shot = <ShotOrder f={f} a={C.order} />;
  else if (f < C.awake) shot = <ShotCollect f={f} a={C.collect} />;
  else if (f < C.duryo2) shot = <Speaker f={f} a={C.awake} look={LOOKS.bhishma} who="none" flip e={{ eye: ease(inv(f, C.awake + 4, C.awake + 14)), look: -0.4 }} dim={0.15} />;
  else if (f < C.bhishma2) shot = <Speaker f={f} a={C.duryo2} look={LOOKS.duryo} who="duryo" flip e={{ brow: 1, wide: 0.6 }} dim={0.1} />;
  else if (f < C.salute) shot = <Speaker f={f} a={C.bhishma2} look={LOOKS.bhishma} who="bhishma" flip e={{ smile: 0.5, brow: 0.2 }} dim={0.1} />;
  else if (f < C.crown) shot = <ShotSalute f={f} a={C.salute} />;
  else if (f < C.feature) shot = <ShotCrown f={f} a={C.crown} />;
  else if (f < C.send) shot = <ShotFeature f={f} a={C.feature} />;
  else shot = <ShotSend f={f} a={C.send} />;

  return (
    <AbsoluteFill style={{ background: "#1a0e08" }}>
      {shot}
      {f >= C.title && f < C.rewind && <ShotTitle f={f} />}
      <Rewind f={f} a={C.rewind} b={C.uttara + 6} />
      <Flash f={f} at={release} len={8} />
      <Flash f={f} at={C.wide} len={6} color="#fff2d0" max={0.7} />
      <Flash f={f} at={BEATS.gandiva[0]} len={10} max={0.8} />
      <Flash f={f} at={BEATS.conch[0]} len={6} max={0.6} />
      <Flash f={f} at={BEATS.astra[0] + 2} len={14} color="#e6dcff" />
      <Flash f={f} at={crownHit} len={6} max={0.7} />
      <Captions f={f} />
      <MuteHook f={f} />
      <BrandBug />
      {audio && <Audio src={staticFile("jyotiq/bharata/special/mix.wav")} />}
    </AbsoluteFill>
  );
};
